INSERT INTO blogs (id,title,summary,image,content,date) VALUES (1,'Cómo elegir tu próximo par','Piensa primero en las actividades de tu día.','https://nikeclprod.vtexassets.com/arquivos/ids/1886501-380-380?v=639252599884100000&width=380&height=380&aspect=true','Piensa primero en las actividades de tu día. Revisa la talla, los materiales y la descripción antes de elegir. Compara las opciones del catálogo y guarda tus favoritas. Esta publicación forma parte del contenido de demostración de SneakerX.','2026-11-23');
INSERT INTO blogs (id,title,summary,image,content,date) VALUES (2,'Cuidados básicos para tus zapatillas','Retira el polvo con un cepillo suave y consulta las indicaciones del fabricante antes de limpiar.','https://nikeclprod.vtexassets.com/arquivos/ids/1715676-380-380?v=639147295356700000&width=380&height=380&aspect=true','Retira el polvo con un cepillo suave y consulta las indicaciones del fabricante antes de limpiar. Deja secar las zapatillas al aire, lejos del calor directo. Mantener una rutina sencilla ayuda a conservar su presentación. Contenido de demostración.','2026-11-22');
INSERT INTO blogs (id,title,summary,image,content,date) VALUES (3,'Ideas para combinar tu colección','Una combinación de colores neutros permite destacar las zapatillas.','https://nikeclprod.vtexassets.com/arquivos/ids/207379-380-380?v=637691521053630000&width=380&height=380&aspect=true','Una combinación de colores neutros permite destacar las zapatillas. Prueba distintos pantalones y accesorios para encontrar un conjunto cómodo para ti. La elección depende de tus preferencias y del uso que darás a cada par. Contenido de demostración.','2026-11-21');
INSERT INTO blogs (id,title,summary,image,content,date) VALUES (4,'Organiza tus zapatillas en casa','Separa los pares de uso diario y guarda los demás en un espacio limpio y ventilado.','https://nikeclprod.vtexassets.com/arquivos/ids/1759042-380-380?v=639203337393330000&width=380&height=380&aspect=true','Separa los pares de uso diario y guarda los demás en un espacio limpio y ventilado. Evita apilarlos de forma que pierdan su forma. Revisa tu colección antes de comprar para identificar qué necesitas. Contenido de demostración.','2026-11-20');
INSERT INTO blogs (id,title,summary,image,content,date) VALUES (5,'Encuentra tu talla con comodidad','Mide ambos pies y consulta la tabla de tallas del fabricante.','https://nikeclprod.vtexassets.com/arquivos/ids/1272484-380-380?v=638798980431070000&width=380&height=380&aspect=true','Mide ambos pies y consulta la tabla de tallas del fabricante. Considera el tipo de calcetín que usarás y prueba el calzado con calma. El ajuste puede variar entre modelos. Esta guía es contenido de demostración del blog.','2026-11-19');
